INSERT INTO `ai_chats` (`id`, `user_id`, `branch_id`, `title`, `created_at`, `updated_at`, `kind`) VALUES
(6, 41, 5, 'Chegirma qoidalari qanday ishlaydi?', '2026-10-02 19:52:21', '2026-10-02 19:52:24', 'help'),
(8, 41, NULL, 'Filial holatini umumiy tahlil qil: qanday kamchiliklar bor v', '2026-10-11 20:11:57', '2026-10-11 20:12:02', 'analytics'),
(9, 41, 5, 'Menejerga ruxsatni qanday beraman?', '2026-10-16 11:05:18', '2026-10-16 11:05:21', 'help');
INSERT INTO `ai_messages` (`id`, `ai_chat_id`, `branch_id`, `user_id`, `role`, `content`, `created_at`) VALUES
(3, 6, 5, 41, 'user', 'Chegirma qoidalari qanday ishlaydi?', '2026-10-02 19:52:24'),
(4, 6, 5, 41, 'assistant', 'Chegirma qoidalari Sozlamalar → Chegirma qoidalari bo‘limida belgilanadi va oldindan to‘lov chegirmasining amal qilish muddatini belgilaydi: guruh boshlanishidan necha kun OLDIN va necha kun KEYIN chegirma berilishi mumkin.\n\nQoidalar ishlashi:\n\n1. O‘quvchi guruh boshlanishidan belgilangan muddat ichida oldindan to‘lov qilsa, chegirma avtomatik beriladi.\n2. To‘lovlar bir necha bo‘lsa ham, jami «narx − chegirma» summasiga yetganda chegirma olinadi.\n3. Chegirma faqat qarzi guruh narxidan oshmagan o‘quvchilarga beriladi.\n4. Har bir guruh uchun chegirma faqat bir marta olinadi.\n\nShuningdek, chegirma summasi Narx rejasi orqali belgilanadi.', '2026-10-02 19:52:24'),
(7, 8, NULL, 41, 'user', 'Filial holatini umumiy tahlil qil: qanday kamchiliklar bor va nima qilish kerak?', '2026-10-11 20:12:02'),
(8, 8, NULL, 41, 'assistant', 'Filial holati tahlili (2026-10-01 dan 2026-10-12 gacha):\n\nXulosa:\n- Sof tushum 67 018 000 so\'m, xarajat 10 722 050 so\'m, ish haqi 24 575 000 so\'m, foyda 31 720 950 so\'m.\n- Yangi o\'quvchilar soni 3 863, faol o\'quvchilar 251, faol guruhlar 39.\n- Qarzdorlar soni 577, jami qarz 232 501 838 so\'m.\n- Murojaatlar juda kam (faqat 1 yangi, qabul qilingan yo\'q, konversiya 0%).\n- Davomad foizi 84.6%.\n\nAniqlangan kamchiliklar:\n1. Qarzdorlar soni yuqori (577 nafar) va qarz miqdori katta (232,5 million so\'m).\n2. Murojaatlar soni va qabul foizi juda past (1 yangi murojaat, 0 qabul qilingan).\n3. Davomad foizi 85% atrofida, bu yaxshiroq bo\'lishi mumkin.\n4. Yangi o\'quvchilar soni ko\'p, ammo faol o\'quvchilar soni nisbatan kam (3863 yangi, 251 faol).\n\nAmaliy tavsiyalar:\n- Qarzdorlarni kamaytirish uchun qarzlarni yopish bo\'yicha kampaniyalar o\'tkazish, eslatmalar va avtomatik SMS yuborishni faollashtirish.\n- Murojaatlar sonini oshirish uchun marketing va reklama faoliyatini kuchaytirish, murojaatlarni qabul qilish jarayonini yaxshilash.\n- Davomadni oshirish uchun o\'qituvchilar va menejerlar bilan ish olib borish, davomadni muntazam nazorat qilish.\n- Faol o\'quvchilar sonini ko\'paytirish uchun yangi o\'quvchilarni faol guruhlarga jalb qilish va qarzli o\'quvchilarni guruhlarga qo\'shishda yordam berish.', '2026-10-11 20:12:02'),
(9, 9, 5, 41, 'user', 'Menejerga ruxsatni qanday beraman?', '2026-10-16 11:05:21'),
(10, 9, 5, 41, 'assistant', 'sAdmin sifatida menejerga ruxsat berish uchun quyidagilarni bajaring:\n\n1. Menyudan **Hodimlar** bo‘limiga kiring.\n2. Menejer sifatida ishlaydigan hodimni toping yoki yangi menejer qo‘shing.\n3. Hodim qatoridagi **Ruxsatlar** tugmasini bosing.\n4. Kerakli ruxsatlarni belgilang va saqlang.\n\nEslatma: Adminlar faqat o‘z filialidagi menejerlarga o‘zida mavjud ruxsatlarni bera oladi, ammo sAdmin barcha filiallar uchun to‘liq ruxsatlarni belgilay oladi. Agar admin ruxsat berolmasa, sAdminga murojaat qilish kerak.', '2026-10-16 11:05:21');
